<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { useI18n } from 'vue-i18n';import { api } from '../api';import AppIcon from '../components/AppIcon.vue'
const {t}=useI18n();const queue=ref<any[]>([]);const index=ref(0);const revealed=ref(false);const mode=ref<'recognition'|'production'>('production');const done=ref(0)
onMounted(async()=>queue.value=await api.get<any[]>('/reviews/due'))
const word=computed(()=>queue.value[index.value])
async function rate(rating:number){if(!word.value)return;await api.post(`/reviews/${word.value.id}`,{rating});done.value++;index.value++;revealed.value=false}
</script>
<template>
  <div class="page review-page">
    <header class="page-head"><h1>{{ t('review.title') }}</h1><div class="review-count"><b>{{ Math.max(0, queue.length - index) }}</b><span>{{ t('review.left') }}</span></div></header>
    <div v-if="word" class="review-stage">
      <div class="mode-toggle"><button :class="{ active: mode === 'production' }" @click="mode = 'production'">{{ t('review.recall') }}</button><button :class="{ active: mode === 'recognition' }" @click="mode = 'recognition'">{{ t('review.recognize') }}</button></div>
      <div class="review-card card">
        <span class="badge">{{ word.language.toUpperCase() }} · {{ index + 1 }} / {{ queue.length }}</span>
        <template v-if="mode === 'production'"><p class="prompt-label">{{ t('review.recallPrompt') }}</p><blockquote>{{ word.source_sentence?.replace(new RegExp(word.term, 'ig'), '_____') || word.meaning }}</blockquote><small>{{ word.meaning }}</small></template>
        <template v-else><p class="prompt-label">{{ t('review.recognizePrompt') }}</p><h2>{{ word.term }}</h2><blockquote>{{ word.source_sentence }}</blockquote></template>
        <button v-if="!revealed" class="btn primary reveal" @click="revealed = true"><AppIcon name="spark" />{{ t('review.showAnswer') }}</button>
        <Transition name="answer"><div v-if="revealed" class="answer"><small>{{ t('review.answer') }}</small><h2>{{ mode === 'production' ? word.term : word.meaning }}</h2><p v-if="word.details?.senses?.[0]?.example">{{ word.details.senses[0].example }}</p></div></Transition>
      </div>
      <div v-if="revealed" class="ratings"><button @click="rate(1)"><b>{{ t('review.again') }}</b><span>{{ t('review.tenMinutes') }}</span></button><button @click="rate(2)"><b>{{ t('review.hard') }}</b><span>{{ t('review.oneDay') }}</span></button><button @click="rate(3)"><b>{{ t('review.good') }}</b><span>{{ t('review.threeDays') }}</span></button><button @click="rate(4)"><b>{{ t('review.easy') }}</b><span>{{ t('review.longer') }}</span></button></div>
    </div>
    <div v-else class="review-done card"><span><AppIcon name="check" :size="28" /></span><h2>{{ done ? t('review.done') : t('review.nothingDue') }}</h2><p>{{ t('review.doneBody') }}</p><RouterLink to="/words" class="btn">{{ t('review.back') }}</RouterLink></div>
  </div>
</template>
<style scoped>.review-page{max-width:880px}.review-count{text-align:right}.review-count b,.review-count span{display:block}.review-count b{font-size:27px;color:var(--green)}.review-count span{font-size:11px;letter-spacing:.1em;color:var(--muted)}.review-stage{max-width:650px;margin:auto}.mode-toggle{display:flex;justify-content:center;margin-bottom:13px}.mode-toggle button{height:31px;padding:0 13px;border:1px solid var(--line);background:transparent;color:var(--muted);font-size:11px}.mode-toggle button:first-child{border-radius:8px 0 0 8px}.mode-toggle button:last-child{border-radius:0 8px 8px 0}.mode-toggle button.active{background:var(--green);color:white;border-color:var(--green)}.review-card{min-height:390px;padding:32px;text-align:center;display:flex;flex-direction:column;align-items:center}.prompt-label{font-size:11px;letter-spacing:.13em;color:var(--muted);margin-top:70px}.review-card blockquote{font-size:19px;line-height:1.7;margin:14px auto;max-width:500px}.review-card>small{font-size:11px;color:var(--muted)}.review-card>h2{font-size:35px;margin:16px 0}.reveal{margin-top:auto}.answer{margin-top:auto;padding-top:22px;border-top:1px solid var(--line);width:100%}.answer small{font-size:11px;color:var(--green);letter-spacing:.1em}.answer h2{font-size:29px;margin:7px}.answer p{font-size:11px;color:var(--muted)}.ratings{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-top:11px}.ratings button{height:56px;border:1px solid var(--line);border-radius:9px;background:var(--paper)}.ratings b,.ratings span{display:block}.ratings b{font-size:11px}.ratings span{font-size:11px;color:var(--muted);margin-top:4px}.ratings button:hover{border-color:var(--green);color:var(--green)}.review-done{padding:60px;text-align:center}.review-done>span{width:58px;height:58px;border-radius:50%;background:var(--lime);color:var(--green);display:grid;place-items:center;margin:auto}.review-done h2{margin:18px 0 7px}.review-done p{font-size:12px;color:var(--muted);margin-bottom:20px}.answer-enter-active{transition:.25s}.answer-enter-from{opacity:0;transform:translateY(7px)}@media(max-width:600px){.review-card{padding:22px;min-height:420px}.ratings{grid-template-columns:1fr 1fr}}</style>
